window.K3_QRAW.push.apply(window.K3_QRAW, [
  {"id": "kc|edu-foreign|wj-04|知识点二|2", "bank": "kc", "subj": "edu-foreign", "ch": "wj-04", "chName": "第四章 西欧中世纪教育", "sec": "知识点二：西欧中世纪教育的综合题", "no": 2, "q": "关于西欧中世纪的教育机构，下列说法正确的是（　）", "opts": ["教区学校是西欧中世纪最典型的教会教育形式", "宫廷学校培养朝臣官员，没有宗教色彩", "骑士教育培养封建骑士，是西欧中世纪最普遍的教育形式", "中世纪大学培养社会所需要的职业人才"], "a": 3, "exp": "此题考查西欧中世纪的教育机构。A.修改：西欧中世纪最典型的教会教育形式是修道院学校。教区学校是面向普通民众的初级教会学校，并非最典型的教会教育形式。B.修改：宫廷学校虽培养朝臣官员，但仍具有浓厚的宗教色彩。西欧中世纪教会对教育影响深远，世俗教育也渗透着宗教内容。C.修改：骑士教育是西欧中世纪封建社会的一种特殊的家庭教育形式，教育对象仅限于贵族子弟，并非最普遍的教育形式。西欧中世纪最普遍的教育形式是教会教育。D.中世纪大学以培养律师、医生、神职人员等职业人才为目标，服务于社会实际需求。√", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 54}},
  {"id": "kc|edu-foreign|wj-04|知识点二|3", "bank": "kc", "subj": "edu-foreign", "ch": "wj-04", "chName": "第四章 西欧中世纪教育", "sec": "知识点二：西欧中世纪教育的综合题", "no": 3, "q": "下列关于西欧中世纪的教育，说法错误的是（　）", "opts": ["该阶段的智力成就低于欧洲历史上任何时期，教育发展是停滞不前或倒退的", "建立了以修道院为中心的学术和教育制度，并保留了一些学术书籍", "城市学校具有一定的职业训练的性质", "中世纪大学为西方高等教育的发展打下了初步基础"], "a": 0, "exp": "此题考查西欧中世纪的教育。A选项中，智力成就指知识方面的学习，中世纪时期将知识局限在宗教知识中，因此发展有限，智力成就低于欧洲历史上任何时期。但这一时期形成了现代大学的雏形，宗教教育、骑士教育等的发展也非常繁荣。此题为选非题，因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 54}},
  {"id": "kc|edu-foreign|wj-04|知识点二|4", "bank": "kc", "subj": "edu-foreign", "ch": "wj-04", "chName": "第四章 西欧中世纪教育", "sec": "知识点二：西欧中世纪教育的综合题", "no": 4, "q": "西欧中世纪教育相对于古希腊、古罗马时期的教育最大的特点是（　）", "opts": ["学术性", "宗教性", "等级性", "职业性"], "a": 1, "exp": "此题考查中世纪的教育特点。在西欧中世纪，基督教是主流意识形态，也是社会最重要的统治力量，因此中世纪教育具有浓厚的宗教色彩，并陷入了思想相对停滞的状态。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 54}},
  {"id": "kc|edu-foreign|wj-04|知识点二|5", "bank": "kc", "subj": "edu-foreign", "ch": "wj-04", "chName": "第四章 西欧中世纪教育", "sec": "知识点二：西欧中世纪教育的综合题", "no": 5, "q": "下列关于各个时期教育内容的描述，不正确的是（　）", "opts": ["中世纪“七艺”—文法、修辞、辩证法、算术、几何、天文、音乐", "中世纪骑马、游泳、投枪、击剑、打猎、弈棋、吟诗“骑士七技”一", "古罗马-赛跑、跳跃、摔跤、掷铁饼、投标枪“五项竞技”—", "古代中国—“六艺”教育—礼、乐、射、御、书、数"], "a": 2, "exp": "此题考查各个时期的教育内容。古希腊崇尚“五项竞技”；古罗马并不崇尚“五项竞技”，而是崇尚角斗竞技。此题为选非题，因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 54}},
  {"id": "kc|edu-foreign|wj-05|知识点一|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-05", "chName": "第五章 文艺复兴与宗教改革时期的教育", "sec": "知识点一：人文主义教育", "no": 1, "q": "人文主义教育的核心是（　）", "opts": ["肯定人的价值", "尊崇感性", "推崇来世享受", "推崇思想保守"], "a": 0, "exp": "此题考查人文主义教育的内涵。人文主义教育的内涵包括：歌颂和赞扬人的价值和尊严；宣扬人的思想解放与个性自由；肯定现世生活的价值和尘世的享乐；提倡学术，尊崇理性；主张人生而平等，批判等级制度。人文主义教育的核心思想是“以人为本”，也就是肯定人的价值。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 55}},
  {"id": "kc|edu-foreign|wj-05|知识点一|2", "bank": "kc", "subj": "edu-foreign", "ch": "wj-05", "chName": "第五章 文艺复兴与宗教改革时期的教育", "sec": "知识点一：人文主义教育", "no": 2, "q": "下列有关人文主义教育的特色，分析不正确的是（　）", "opts": ["反对权威主义，崇尚自由", "认为教育应该遵循儿童身心发展的规律", "批判经院主义的烦琐方法，注重能力培养", "反对一切宗教教育模式"], "a": 3, "exp": "此题考查人文主义教育。人文主义教育具有宗教性，几乎所有的人文主义教育家都信仰上帝。他们虽然坪击天主教会的端，但不反对宗教，更不打算消灭宗教。他们希望以世俗和人文精神改造中世纪专横的宗教性，以造就一种更富世俗色彩和人性色彩的宗教性。此题为选非题，因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 55}},
  {"id": "kc|edu-foreign|wj-05|知识点一|3", "bank": "kc", "subj": "edu-foreign", "ch": "wj-05", "chName": "第五章 文艺复兴与宗教改革时期的教育", "sec": "知识点一：人文主义教育", "no": 3, "q": "下列选项中，不属于人文主义教育的基本特征的是（　）", "opts": ["世俗性和宗教性并举", "贵族性和大众性并举", "古典主义和世俗性并举", "人本主义和批判性并举"], "a": 1, "exp": "此题考查人文主义教育的基本特征。（1）人文主义教育的基本特征是世俗性、宗教性、贵族性、人本主义和古典主义，不包括大众性。大众性即平民性。人文主义教育是贵族上层社会的思想解放运动，未进人平民社会，而后续引发的宗教改革具有平民性。（2）批判性成立的原因：人文主义教育批判经院哲学的教条主义，提倡人的世俗性。此题为选非题，因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 55}},
  {"id": "kc|edu-foreign|wj-05|知识点一|4", "bank": "kc", "subj": "edu-foreign", "ch": "wj-05", "chName": "第五章 文艺复兴与宗教改革时期的教育", "sec": "知识点一：人文主义教育", "no": 4, "q": "人文主义教育与中世纪教育的根本区别是具有（　）", "opts": ["宗教性", "科学性", "贵族性", "世俗性"], "a": 3, "exp": "此题考查人文主义教育与中世纪教育。人文主义具有浓厚的世俗精神，教育更关注今生而非来世；中世纪教育显著的特点是基督教教育的繁荣及其对学校教育的影响。这是人文主义教育与中世纪教育的根本区别。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 55}},
  {"id": "kc|edu-foreign|wj-05|知识点一|5", "bank": "kc", "subj": "edu-foreign", "ch": "wj-05", "chName": "第五章 文艺复兴与宗教改革时期的教育", "sec": "知识点一：人文主义教育", "no": 5, "q": "文艺复兴时期，由人文主义教育家维多里诺创办的，被誉为“欧洲第一所人文主义学校”的是（　）", "opts": ["儿童之家", "贫儿之家", "乡村教育之家", "快乐之家"], "a": 3, "exp": "此题考查人文主义教育家的思想。A.儿童之家：由蒙台梭利创办。B.贫儿之家：由裴斯泰洛齐创办。C.乡村教育之家：由利茨创办。D.快乐之家：由维多里诺创办。√】“快乐之家”的学生多为贵族富豪子弟，也有少数贫民中的天才儿童。6、7岁入学，20岁毕业，从小学一直到大学，修业年限约15年。此题为选非题，因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 55}},
  {"id": "kc|edu-foreign|wj-05|知识点一|6", "bank": "kc", "subj": "edu-foreign", "ch": "wj-05", "chName": "第五章 文艺复兴与宗教改革时期的教育", "sec": "知识点一：人文主义教育", "no": 6, "q": "维多里诺采用多种方式进行教学，以下不是维多里诺倡导的教育的是（　）", "opts": ["快乐教育", "个性教育", "专业教育", "古典教育"], "a": 2, "exp": "此题考查维多里诺的教育观。A.快乐教育：维多里诺强调学习环境应愉悦宜人，教学要尊重儿童兴趣。B.个性教育：维多里诺主张因材施教，根据学生的不同特点、能力进行个别指导。C.专业教育：维多里诺的教育目标是培养身心和谐发展的“通才”，即全面发展的人，而不是培养某一专门职业的人才。此题为选非题。√D.古典教育：维多里诺以希腊文、拉丁文、古典哲学为核心课程。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 55}},
  {"id": "kc|edu-foreign|wj-05|知识点一|7", "bank": "kc", "subj": "edu-foreign", "ch": "wj-05", "chName": "第五章 文艺复兴与宗教改革时期的教育", "sec": "知识点一：人文主义教育", "no": 7, "q": "弗吉里奥是率先阐述人文主义教育思想的学者，其思想大大受益于（　）", "opts": ["柏拉图", "西塞罗", "昆体良", "亚里士多德"], "a": 2, "exp": "此题考查弗吉里奥的教育思想。意大利的弗吉里奥是率先阐述人文主义教育思想的学者，其思想大大受益于昆体良，并为昆体良的《雄辩术原理》作注释。其论文《论绅士风度与自由学科》最能体现他的教育思想。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 55}},
  {"id": "kc|edu-foreign|wj-05|知识点一|8", "bank": "kc", "subj": "edu-foreign", "ch": "wj-05", "chName": "第五章 文艺复兴与宗教改革时期的教育", "sec": "知识点一：人文主义教育", "no": 8, "q": "主张基督教与人文主义并重，即人文主义基督教化、基督教人文主义化的教育家是（　）", "opts": ["伊拉斯谟", "斯图谟", "奥古斯丁", "弗吉里奥"], "a": 0, "exp": "此题考查伊拉斯谟的教育思想。A.伊拉斯谟是一位基督教人文主义教育理论家，他并不像意大利人文主义者那样过于偏重古典文化，而是主张基督教与人文主义并重，即人文主义基督教化、基督教人文主义化。√B.斯图谟是马丁·路德思想的践行者之一，他创建并完善了新教中学。C.奥古斯丁是罗马帝国后期的神学家、哲学家，创立了基督教宗教哲学体系。D.弗吉里奥是率先阐述人文主义教育思想的学者，并未讨论神学。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 55}},
  {"id": "kc|edu-foreign|wj-05|知识点一|9", "bank": "kc", "subj": "edu-foreign", "ch": "wj-05", "chName": "第五章 文艺复兴与宗教改革时期的教育", "sec": "知识点一：人文主义教育", "no": 9, "q": "意大利和北欧人文主义教育思想的共同点不包括（　）", "opts": ["走向形式主义", "重视教育与社会的联系", "培养君主与朝臣", "重视古典学科和古典语言"], "a": 2, "exp": "此题考查意大利和北欧人文主义教育思想的异同点。意大利和北欧人文主义教育思想对比表维度意大利人文主义教育思想北欧人文主义教育思想教育性质：具有较强的世俗性教育性质：宗教虔诚与世俗道德并重不同点教育目的：培养城市公民，注重个人全面发展教育目的：培养君主与朝臣续表意大利人文主义教育思想北欧人文主义教育思想维度教育内容：重视古典学科与古典语言相同点重视教育与社会的联系后期表现出形式主义意大利为共和体制，其教育目的是培养富有自由、平等精神的公民；而北欧人文主义教育家崇尚君主制，教育目的是培养具有人文主义精神的君主和朝臣。此题为选非题，因此，答案选C。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 55}},
  {"id": "kc|edu-foreign|wj-05|知识点一|10", "bank": "kc", "subj": "edu-foreign", "ch": "wj-05", "chName": "第五章 文艺复兴与宗教改革时期的教育", "sec": "知识点一：人文主义教育", "no": 10, "q": "在人文主义者看来，培养美德最好的方式是（　）", "opts": ["学习圣经", "学习神学", "学习古典文化", "学习自然科学"], "a": 2, "exp": "此题考查人文主义教育家的教育思想。人文主义者强调古典学科的重要性，把古典科目作为人文主义课程的基础和主体，并强调培养美德最好的方式是学习古典文化。因此，答案选C。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 56}},
  {"id": "kc|edu-foreign|wj-05|知识点二|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-05", "chName": "第五章 文艺复兴与宗教改革时期的教育", "sec": "知识点二：新教教育", "no": 1, "q": "马丁·路德强调教育目的具有宗教性和世俗性的双重属性。在教育的管理权上，他主张（　）", "opts": ["国家和教会都对教育负有责任", "国家通过教会管理学校", "教育权由国家而不是由教会掌握", "教育权由教会而不是由国家掌握"], "a": 2, "exp": "此题考查马丁·路德的教育思想。马丁·路德认为，尽管教育目的是双重的，但教育管理权的归属是唯一的，教育的管理权应完全归于世俗政权一—国家。因此，答案选C。·", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 56}},
  {"id": "kc|edu-foreign|wj-05|知识点二|2", "bank": "kc", "subj": "edu-foreign", "ch": "wj-05", "chName": "第五章 文艺复兴与宗教改革时期的教育", "sec": "知识点二：新教教育", "no": 2, "q": "文艺复兴与宗教改革时期的加尔文派教育实践的主要特点不包括（　）", "opts": ["重视使用本民族语言教学", "重视学生兴趣", "主张政教分离，教育独立于教会", "推行免费的普及教育"], "a": 2, "exp": "此题考查加尔文派新教的教育观与教育实践。A.加尔文派在初级教育中重视使用本民族语言教学，目的是让普通民众能直接理解《圣经》和宗教教义。B.重视学生兴趣属于路德派和加尔文派共同的教育方法。C.加尔文派主张政教合一，教育由教会主导，政府配合推行，而非政教分离。此题为选非题。√D.加尔文派在日内瓦明确推行免费的普及教育，推动初等教育的普及，规定所有男女儿童都必须入学学习基础文化和宗教知识。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 56}},
  {"id": "kc|edu-foreign|wj-05|知识点二|3", "bank": "kc", "subj": "edu-foreign", "ch": "wj-05", "chName": "第五章 文艺复兴与宗教改革时期的教育", "sec": "知识点二：新教教育", "no": 3, "q": "下列不属于加尔文派和路德派共同特点的是（　）", "opts": ["都具有宗教性与世俗性", "贵族性与平民性兼具", "神学和理性思维方式并存", "重视古典语和民族语教学"], "a": 3, "exp": "此题考查加尔文派和路德派的教育主张。A.二者都具有宗教性与世俗性的双重属性。B.二者都在不同地区、不同时期，获得过贵族和平民的支持，所以可以体现贵族性和平民性。C.二者的改革既体现重视神学，又重视人文主义与学术研究，体现出了理性思维。D.二者并不重视古典语和民族语共同教学，而是更加重视民族语教学，发展各民族的语言。此题为选非题。√", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 56}},
  {"id": "kc|edu-foreign|wj-05|知识点二|4", "bank": "kc", "subj": "edu-foreign", "ch": "wj-05", "chName": "第五章 文艺复兴与宗教改革时期的教育", "sec": "知识点二：新教教育", "no": 4, "q": "英国国教派的教育制度是（　）", "opts": ["国家通过教会管理学校", "教会完全掌握教育权", "教会通过国家管理学校", "教育独立于国家和教会"], "a": 0, "exp": "此题考查英国国教派的教育。英国国教派的教育改革在本质上是当时的英国国王想要夺取教皇在英国所具有的权力和教会的财产而产生的，因此其目的必然是让国家取代教会掌握教育权，只是由于各种因素未能完全实现，最终形成国家通过教会管理学校的教育制度。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 56}},
  {"id": "kc|edu-foreign|wj-05|知识点二|5", "bank": "kc", "subj": "edu-foreign", "ch": "wj-05", "chName": "第五章 文艺复兴与宗教改革时期的教育", "sec": "知识点二：新教教育", "no": 5, "q": "下列关于宗教改革中各教派的说法，错误的是（　）", "opts": ["路德派主张强制义务教育", "加尔文派主张实行免费义务教育", "英国国教派严格控制师生思想", "天主教教育改革的质量与效率低于其他教派"], "a": 3, "exp": "此题考查宗教改革。D选项中，天主教教育改革的目的是恢复天主教在欧洲的统治，是倒行逆施的。但在与新教各派竞争中，天主教教育在理论和实践上吸纳各派教育之长，汇集当时人文主义教育许多有效的教学主张，实现了内容体系化、方法综合化、管理规范化，因此教育质量与效率均高于其他教派。此题为选非题，因此，答案选D。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 56}},
  {"id": "kc|edu-foreign|wj-05|知识点三|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-05", "chName": "第五章 文艺复兴与宗教改革时期的教育", "sec": "知识点三：天主教教育", "no": 1, "q": "耶稣会学校的教育目的主要是（　）", "opts": ["培养具有新教信仰的世俗领袖", "通过精英教育巩固天主教势力", "推行全民免费义务教育", "传播人文主义思想"], "a": 1, "exp": "此题考查耶稣会学校的教育目的。A.耶稣会属于天主教阵营，其反对新教，并不培养新教信仰者。B.耶稣会学校主要面向贵族和上层社会子弟，培养忠诚于天主教的精英人才，以维护天主教的地位。√C.耶稣会学校以精英教育为主，而非面向普通民众的义务教育，且免费并非其核心目的。D.耶稣会学校用人文主义精神来改革学校和教学，客观上促进了教育的近代化发展，但传播人文主义思想并不是其目的。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 56}},
  {"id": "kc|edu-foreign|wj-05|知识点三|2", "bank": "kc", "subj": "edu-foreign", "ch": "wj-05", "chName": "第五章 文艺复兴与宗教改革时期的教育", "sec": "知识点三：天主教教育", "no": 2, "q": "下列有关耶稣会学校的教学方式，描述不正确的一项是（　）", "opts": ["采用了寄宿制和全日制", "经常使用体罚", "采取分班教学的模式", "提倡温和纪律、爱的管理方式"], "a": 1, "exp": "此题考查耶稣会学校。耶稣会学校提倡温和纪律、爱的管理方式，强调师生间的亲密关系，主张废除体罚。此题为选非题，因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 56}},
  {"id": "kc|edu-foreign|wj-05|知识点三|3", "bank": "kc", "subj": "edu-foreign", "ch": "wj-05", "chName": "第五章 文艺复兴与宗教改革时期的教育", "sec": "知识点三：天主教教育", "no": 3, "q": "下列关于耶稣会教育办学重心的表述，正确的是（　）", "opts": ["初等、中等、高等教育均衡发展", "重点发展初等教育，兼顾中等教育", "集中力量发展中等和高等教育", "只专注高等教育，不办中等教育"], "a": 2, "exp": "此题考查耶稣会学校。出于培养精英以控制未来的统治阶层的考虑，耶稣会集中力量发展中等教育和高等教育，不重视初等教育。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 56}},
  {"id": "kc|edu-foreign|wj-05|知识点四|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-05", "chName": "第五章 文艺复兴与宗教改革时期的教育", "sec": "知识点四：综合题", "no": 1, "q": "天主教教育和新教教育的主要区别是（　）", "opts": ["前者具有贵族性，后者具有平民性", "前者重视古典主义，后者重视人本主义", "前者具有宗教性，后者具有世俗性", "前者采用体罚，后者更加温和"], "a": 0, "exp": "此题考查天主教教育和新教教育。A.天主教教育具有贵族性，新教教育具有平民性。√B.天主教教育与新教教育都重视古典主义与人本主义。C.天主教教育与新教教育都具有宗教性和世俗性。D.天主教教育与新教教育在教学管理方面都逐渐取消体罚，注重身心的全面发展。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 56}},
  {"id": "kc|edu-foreign|wj-05|知识点四|2", "bank": "kc", "subj": "edu-foreign", "ch": "wj-05", "chName": "第五章 文艺复兴与宗教改革时期的教育", "sec": "知识点四：综合题", "no": 2, "q": "下列关于人文主义教育、新教教育、天主教教育的说法，错误的是（　）", "opts": ["人文主义教育不含有宗教因素，新教教育和天主教教育都是宗教教育", "人文主义教育、新教教育、天主教教育都重视古典主义和人本主义", "人文主义教育具有贵族性，新教教育具有较强的群众性和普及性", "人文主义教育、新教教育、天主教教育的根本差异在于它们所服务的目的不同"], "a": 0, "exp": "此题考查人文主义教育、天主教教育和新教教育。它们都信仰上帝，但是程度不同。人文主义教育有宗教性，同时也有异教因素；新教教育和天主教教育都是宗教教育，都反对人文主义教育中的一些异教倾向，宗教改革运动中具有宗教性和世俗性双重目的；天主教教育是想恢复到宗教性更强的中世纪。此题为选非题，因此，答案选A。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 56}},
  {"id": "kc|edu-foreign|wj-06|知识点一|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-06", "chName": "第六章 英国的近现代教育制度", "sec": "知识点一：17一18世纪的英国近代教育概况", "no": 1, "q": "下列关于公学的说法，错误的是（　）", "opts": ["公学是面向贵族子弟招生的中等私立学校", "公学受国家教育行政部门干涉与管理", "公学的教育目的是使学生升人学术型大学", "公学被誉为“英国绅士的摇篮"], "a": 1, "exp": "．记忆题此题考查公学。公学是典型的贵族学校，属于私立学校，不受国家教育行政部门干涉。此题为选非题，因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 57}},
  {"id": "kc|edu-foreign|wj-06|知识点一|2", "bank": "kc", "subj": "edu-foreign", "ch": "wj-06", "chName": "第六章 英国的近现代教育制度", "sec": "知识点一：17一18世纪的英国近代教育概况", "no": 2, "q": "17一18世纪，英国建立了一种面向大贵族和大资产阶级子弟的贵族性公学。这类学校的特点是（　）", "opts": ["属于公立学校、公开场所上课、实施公共教育", "公众团体集资、提供公平教育、属于公立学校", "公众团体集资、培养公职人员、公开场所上课", "培养公职人员、属于公益教育、提供公平教育"], "a": 2, "exp": "此题考查公学。公学是由公众团体集资兴办，培养一般公职人员，其学生在公开场所接受教育的中等私立学校，是典型的贵族学校。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 57}},
  {"id": "kc|edu-foreign|wj-06|知识点一|3", "bank": "kc", "subj": "edu-foreign", "ch": "wj-06", "chName": "第六章 英国的近现代教育制度", "sec": "知识点一：17一18世纪的英国近代教育概况", "no": 3, "q": "17一18世纪，英国出现了由公众团体集资兴办的培养公职人员的公学。公学的学习内容不包括（　）", "opts": ["古典语言、古典知识", "上层礼仪", "军事体育", "自然科学知识"], "a": 3, "exp": "此题考查英国公学的教育内容。公学注重古典语言、古典知识的学习和上层社会礼仪的培养，同时还进行体育和军事训练，注重绅士风度的养成。此题为选非题，因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 57}},
  {"id": "kc|edu-foreign|wj-06|知识点一|4", "bank": "kc", "subj": "edu-foreign", "ch": "wj-06", "chName": "第六章 英国的近现代教育制度", "sec": "知识点一：17一18世纪的英国近代教育概况", "no": 4, "q": "）是约翰·弥尔顿设想的学校。这种学校既为升学青年服务，也为就业青年服务，它的实用倾向代表了近代中等教育发展的方向。（　）", "opts": ["学园", "公学", "文法学校", "实科中学"], "a": 0, "exp": "此题考查学园。A.学园是约翰·弥尔顿设想的学校，这种学校既为升学青年服务，也为就业青年服务。√B.公学是由公众团体集资兴办，培养一般公职人员，学生在公开场所接受教育的中等私立学校。C.文法学校是早在中世纪就在欧洲等地出现的中等教育机构，以培养神职人员和官吏为目标。D.实科中学是专为中产阶级子弟设立的学校，主要学习现代语、数学和自然科学等实用学科。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 57}},
  {"id": "kc|edu-foreign|wj-06|知识点一|5", "bank": "kc", "subj": "edu-foreign", "ch": "wj-06", "chName": "第六章 英国的近现代教育制度", "sec": "知识点一：17一18世纪的英国近代教育概况", "no": 5, "q": "17一18世纪，与传统的古典大学相比，高度自治、面向中小资产阶级子弟、学习自然科学和现代外语的大学是（　）", "opts": ["苏格兰大学", "牛津大学", "剑桥大学", "伦敦大学"], "a": 0, "exp": "A记忆题此题考查苏格兰大学。牛津大学与剑桥大学是英国传统的古典大学，排除B、C选项。伦敦大学成立于19世纪，与新大学运动相关，排除D选项。苏格兰大学不依赖政府，高度自治，与社会的联系较为密切。与传统古典大学相比，苏格兰大学比较注重自然科学和现代外语等实用课程的开设，招收中小资产阶级的子弟人学，收费低廉。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 57}},
  {"id": "kc|edu-foreign|wj-06|知识点一|6", "bank": "kc", "subj": "edu-foreign", "ch": "wj-06", "chName": "第六章 英国的近现代教育制度", "sec": "知识点一：17一18世纪的英国近代教育概况", "no": 6, "q": "17—18世纪，英国在教育管理方面的特征是（　）", "opts": ["开创了国家通过拨款间接干预教育的先河", "开始建立中央和地方友好合作关系", "继续中央和地方友好合作关系", "自由放任政策"], "a": 3, "exp": "此题考查17一18世纪英国的教育管理。17一18世纪，英国在教育管理方面的特征是自由放任政策；19世纪，英国开创了国家通过拨款间接干预教育的先河；“二战”前，英国通过《巴尔福教育法》开始建立中央和地方友好合作关系；“二战”后至20世纪80年代和90年代，继续中央和地方友好合作关系。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 57}},
  {"id": "kc|edu-foreign|wj-06|知识点二|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-06", "chName": "第六章 英国的近现代教育制度", "sec": "知识点二：19世纪的英国近代教育概况", "no": 1, "q": "19世纪英国盛行的导生制主要在（）实施。（　）", "opts": ["初等教育", "中等教育", "高等教育", "职业教育"], "a": 0, "exp": "此题考查导生制。19世纪上半叶，英国初等教育主要由宗教团体和慈善机构办理，教育质量低下，师资极为短缺。于是，导生制盛行起来。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 57}},
  {"id": "kc|edu-foreign|wj-06|知识点二|2", "bank": "kc", "subj": "edu-foreign", "ch": "wj-06", "chName": "第六章 英国的近现代教育制度", "sec": "知识点二：19世纪的英国近代教育概况", "no": 2, "q": "19世纪上半叶，英国初等教育师资力量极其匮乏，于是贝尔采用了（）的教学方法，将其改编为导生制。（　）", "opts": ["古代印度", "古代希伯来", "古代巴比伦", "古代埃及"], "a": 0, "exp": "此题考查导生制。古代印度的古儒学校善用导生制，即教师用年长儿童充当助手，由助手协助教师把知识传给一般儿童。这种方法后来被英国教师贝尔所袭用，19世纪在英国成为盛行一时的导生制。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 58}},
  {"id": "kc|edu-foreign|wj-06|知识点二|3", "bank": "kc", "subj": "edu-foreign", "ch": "wj-06", "chName": "第六章 英国的近现代教育制度", "sec": "知识点二：19世纪的英国近代教育概况", "no": 3, "q": "英国初等国民教育制度正式形成的标志是（）的正式颁布。（　）", "opts": ["《巴尔福教育法》", "《福斯特法案》", "《巴特勒教育法》", "《哈多报告》"], "a": 1, "exp": "此题考查《福斯特法案》。英国《初等教育法》（又称《福斯特法案》）的颁布，标志着英国初等国民教育制度的正式形成。从此，英国出现了公立、私立学校并存的局面。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 58}},
  {"id": "kc|edu-foreign|wj-06|知识点二|4", "bank": "kc", "subj": "edu-foreign", "ch": "wj-06", "chName": "第六章 英国的近现代教育制度", "sec": "知识点二：19世纪的英国近代教育概况", "no": 4, "q": "标志着英国新大学运动开始的是（）的成立。（　）", "opts": ["伦敦大学学院", "剑桥大学学院", "牛津大学学院", "耶鲁大学学院"], "a": 0, "exp": "此题考查新大学运动。1828年，伦敦大学学院的成立标志着新大学运动的开始。B、C、D选项的学院名称并不存在，对应的剑桥大学和牛津大学是英国传统大学，耶鲁大学是美国大学。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 58}},
  {"id": "kc|edu-foreign|wj-06|知识点二|5", "bank": "kc", "subj": "edu-foreign", "ch": "wj-06", "chName": "第六章 英国的近现代教育制度", "sec": "知识点二：19世纪的英国近代教育概况", "no": 5, "q": "19世纪，在一些具有自由主义思想的非国教派人士、重视科学发展的世俗学者以及工业资本家等人物的推动下，英国开始了新大学运动。该运动中建立的新式大学主要是为了满足（）子弟的需要。（　）", "opts": ["资产阶级", "中产阶级", "无产阶级", "工人阶级"], "a": 1, "exp": "此题考查新大学运动。新式大学主要以中产阶级为教育对象，采取寄宿和走读两种制度，收费低廉，满足中产阶级子弟的需要。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 58}},
  {"id": "kc|edu-foreign|wj-06|知识点二|6", "bank": "kc", "subj": "edu-foreign", "ch": "wj-06", "chName": "第六章 英国的近现代教育制度", "sec": "知识点二：19世纪的英国近代教育概况", "no": 6, "q": "19世纪40年代，英国大学推广运动主要满足了普通民众接受高等教育的机会，其最主要的做法是（　）", "opts": ["全日制大学以讲座形式将教育推广到社会", "建立新式大学", "既注重古典知识，也注重实用知识", "采取寄宿和走读两种制度"], "a": 0, "exp": "此题考查英国大学推广运动。19世纪40年代，尽管伦敦大学和城市学院的创建拓展了中产阶级的教育机会，但是普通民众接受高等教育的机会仍然有限，大学推广运动就是在这种背景下兴起的。其最主要的特点是伦敦大学、牛津大学、剑桥大学等全日制大学以校内或校外讲座形式将教育推广到非全日制学生。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 58}},
  {"id": "kc|edu-foreign|wj-06|知识点二|7", "bank": "kc", "subj": "edu-foreign", "ch": "wj-06", "chName": "第六章 英国的近现代教育制度", "sec": "知识点二：19世纪的英国近代教育概况", "no": 7, "q": "下列关于新大学运动和大学推广运动的说法，错误的是（　）", "opts": ["新大学运动和大学推广运动是德国高等教育改革的体现", "亲新大学运动中学院传授以自然科学学科为主的知识，排斥宗教课程", "亲新大学运动使高等教育从此面向中产阶级子弟开放", "大学推广运动加强了大学与社会的联系，强化了大学的社会服务职能"], "a": 0, "exp": "此题考查新大学运动和大学推广运动。新大学运动和大学推广运动是19世纪英国高等教育发展的主要表现，而不是德国。此题为选非题，因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 58}},
  {"id": "kc|edu-foreign|wj-06|知识点二|8", "bank": "kc", "subj": "edu-foreign", "ch": "wj-06", "chName": "第六章 英国的近现代教育制度", "sec": "知识点二：19世纪的英国近代教育概况", "no": 8, "q": "19世纪的英国教育较17一18世纪的英国教育进步之处在于（　）", "opts": ["在教育管理上，出现了国家对教育的直接管理", "在初等教育上，通过《初等教育法》建立公立的初等教育制度", "在中等教育上，采用汤顿委员会的建议，沿袭旧制，主要由文法中学和公学开展", "在高等教育上，开始了新大学运动和大学推广运动，古典大学几乎已经不存在"], "a": 1, "exp": "此题考查英国19世纪的教育。A.在教育管理上，国家对教育是间接管理。B.在初等教育上，1870年的《初等教育法》建立了公立的初等教育制度。√C.汤顿委员会提出的建议是建立新式中等教育，不是沿袭旧制，而且其建议并没有被采纳。D.英国开始新大学运动和大学推广运动后，古典大学还存在，并不断改进。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 58}},
  {"id": "kc|edu-foreign|wj-06|知识点三|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-06", "chName": "第六章 英国的近现代教育制度", "sec": "知识点三：20世纪上半叶的英国现代教育制度", "no": 1, "q": ")，建立了中央与地方友好合作、以地方为主的教育管理体制。20世纪初，英国通过了（　）", "opts": ["《费舍教育法》", "《巴尔福教育法》", "《哈多报告》", "《斯宾斯报告》"], "a": 1, "exp": "此题考查《巴尔福教育法》。A.《费舍教育法》核心是普及初等义务教育，真正实现了公立初等学校的免费教育。深联系微信1931637日8日B.1902年，英国通过了《巴尔福教育法》，该法案形成了以地方教育当局为主体的英国教育行政体制，突出了英国的教育管理是由中央和地方以合作伙伴的方式来完成的。√C.《哈多报告》提出初等教育和中等教育的衔接方案，以及中等教育面向全体儿童的思想。D.《斯宾斯报告》在《哈多报告》基础上，强调中等教育的多样化，提出设立多科性学校。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 58}},
  {"id": "kc|edu-foreign|wj-06|知识点三|2", "bank": "kc", "subj": "edu-foreign", "ch": "wj-06", "chName": "第六章 英国的近现代教育制度", "sec": "知识点三：20世纪上半叶的英国现代教育制度", "no": 2, "q": "英国教育史上第一次明确宣布教育立法的实施“要考虑到建立面向全体有能力受益的人的全国公共教育制度”的法案是（　）", "opts": ["《福斯特法案》", "《巴尔福教育法》", "《费舍教育法》", "《巴特勒教育法》"], "a": 2, "exp": "此题考查《费舍教育法》。A.《福斯特法案》标志着英国初等国民教育制度的正式形成。B.《巴尔福教育法》重点是调整教育管理体制，使英国形成了以地方教育当局为主体的教育行政体制。C.《费舍教育法》首次建立了公共教育制度。它是英国教育史上第一次明确宣布教育立法的实施“要考虑到建立面向全体有能力受益的人的全国公共教育制度”。√D.《巴特勒教育法》基本形成了现代英国国民教育制度。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 58}},
  {"id": "kc|edu-foreign|wj-06|知识点三|3", "bank": "kc", "subj": "edu-foreign", "ch": "wj-06", "chName": "第六章 英国的近现代教育制度", "sec": "知识点三：20世纪上半叶的英国现代教育制度", "no": 3, "q": "《费舍教育法》未触及的问题是（　）", "opts": ["继续教育问题", "初等教育问题", "幼儿教育问题", "双轨制问题"], "a": 3, "exp": "此题考查《费舍教育法》。《费舍教育法》的主要内容有：（1）加强地方教育当局发展教育的权力和国家教育委员会制约地方教育当局的权限；（2）地方教育当局为2～5岁的儿童开设幼儿学校；（3）规定5～14岁为义务教育阶段，小学一律实行免费教育；（4）地方教育当局应建立和维持继续教育学校。该法案未涉及双轨制。因此；答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 58}},
  {"id": "kc|edu-foreign|wj-06|知识点三|4", "bank": "kc", "subj": "edu-foreign", "ch": "wj-06", "chName": "第六章 英国的近现代教育制度", "sec": "知识点三：20世纪上半叶的英国现代教育制度", "no": 4, "q": "在英国教育史上，第一次从国家角度阐明“中等教育面向全体儿童”的法案是（　）", "opts": ["《1988年教育改革法》", "《哈多报告》", "《福斯特法案》", "《巴特勒教育法》"], "a": 1, "exp": "此题考查《哈多报告》。1926年颁布的《哈多报告》是英国教育史上第一次从国家角度阐明“中等教育面向全体儿童”的法案。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 58}},
  {"id": "kc|edu-foreign|wj-06|知识点三|5", "bank": "kc", "subj": "edu-foreign", "ch": "wj-06", "chName": "第六章 英国的近现代教育制度", "sec": "知识点三：20世纪上半叶的英国现代教育制度", "no": 5, "q": "20世纪20年代英国颁布的《哈多报告》，被视为现代英国教育发展的里程碑之一，其意义不包括（　）", "opts": ["以11岁考试分流突出考试的公平性", "满足社会上不同阶层对中等教育的需要", "从国家角度阐明中等教育面向全体儿童的思想", "促进了未来综合中学的发展"], "a": 3, "exp": "此题考查《哈多报告》。A、B、C选项正确。D选项属于《斯宾斯报告》的意义，该报告提出了多科性中学的设想，促进了未来综合中学的发展。此题为选非题，因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 59}},
  {"id": "kc|edu-foreign|wj-06|知识点三|6", "bank": "kc", "subj": "edu-foreign", "ch": "wj-06", "chName": "第六章 英国的近现代教育制度", "sec": "知识点三：20世纪上半叶的英国现代教育制度", "no": 6, "q": "）不仅肯定了《哈多报告》的发展方向，更明确设想了要开办一种多科性学校。英国颁布的（　）", "opts": ["《罗宾斯报告》", "《斯宾斯报告》", "《巴特勒教育法》", "《费舍教育法》"], "a": 1, "exp": "此题考查《斯宾斯报告》。A.《罗宾斯报告》探讨了英国高等教育如何为社会服务的问题，提出了“罗宾斯原则”。B.《斯宾斯报告》把《哈多报告》中的双轨改成三轨，即文法中学、现代中学、技术中学，同时提出了设立一种兼有文法、现代和技术学科的多科性中学的设想。√C.《巴特勒教育法》基本形成了现代英国国民教育制度。D.《费舍教育法》核心是普及初等义务教育，真正实现了公立初等学校的免费教育。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 59}},
  {"id": "kc|edu-foreign|wj-06|知识点三|7", "bank": "kc", "subj": "edu-foreign", "ch": "wj-06", "chName": "第六章 英国的近现代教育制度", "sec": "知识点三：20世纪上半叶的英国现代教育制度", "no": 7, "q": "下列关于英国的教育法案，按照时间顺序由早到晚排列正确的是（　）", "opts": ["《费舍教育法》《巴尔福教育法》《哈多报告》《斯宾斯报告》", "《巴尔福教育法》《费舍教育法》《哈多报告》《斯宾斯报告》", "《费舍教育法》《巴尔福教育法》《斯宾斯报告》《哈多报告》", "《巴尔福教育法》《费舍教育法》《斯宾斯报告》《哈多报告》"], "a": 1, "exp": "此题考查英国的教育法案。（1）1902年，为了公平分配教育补助金和加强对地方教育的管理，英国通过了《巴尔福教育法》。（2）1918年，英国国会通过了教育大臣费舍提出的关于初等教育的法案，即《费舍教育法》。（3）1926—1933年，以哈多为主席的调查委员会提出了《哈多报告》。（4）1938年，英国政府颁布了以改革中等教育为中心的《斯宾斯报告》。：因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 59}},
  {"id": "kc|edu-foreign|wj-06|知识点四|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-06", "chName": "第六章 英国的近现代教育制度", "sec": "知识点四：20世纪下半叶的英国现代教育制度", "no": 1, "q": "《巴特勒教育法》是英国“二战”后第一个里程碑法案，其主要贡献是（　）", "opts": ["形成了英国初等国民教育制度", "形成了英国现代国民教育制度", "形成了中央与地方友好合作，以地方为主的教育管理体制", "形成了英国高等教育的“双重制"], "a": 1, "exp": "此题考查《巴特勒教育法》。A.形成了英国初等国民教育制度一一《初等教育法》B：形成了英国现代国民教育制度一—《巴特勒教育法》。√C.形成了中央与地方友好合作、以地方为主的教育管理体制一《巴尔福教育法》。：D.形成了英国高等教育的“双重制”一“双重制”形成于20世纪60年代，终结于《1992年继续教育和高等教育法》。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 59}},
  {"id": "kc|edu-foreign|wj-06|知识点四|2", "bank": "kc", "subj": "edu-foreign", "ch": "wj-06", "chName": "第六章 英国的近现代教育制度", "sec": "知识点四：20世纪下半叶的英国现代教育制度", "no": 2, "q": "《1944年教育法》要求实施的义务教育年龄阶段是（　）", "opts": ["5~12岁", "5~14岁", "5~15岁", "5~16岁"], "a": 2, "exp": "此题考查英国各法案的义务教育年龄。A.《初等教育法》要求对5～12岁的儿童实施强迫性初等教育。B.《费舍教育法》规定5～14岁为义务教育阶段。C.《1944年教育法》要求实施5～15岁的义务教育。√D:《1988年教育法》确定5～16岁为义务教育阶段。（说明：此题解析也是对英国义务教育年龄的总结。）", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 59}},
  {"id": "kc|edu-foreign|wj-06|知识点四|3", "bank": "kc", "subj": "edu-foreign", "ch": "wj-06", "chName": "第六章 英国的近现代教育制度", "sec": "知识点四：20世纪下半叶的英国现代教育制度", "no": 3, "q": "《巴特勒教育法》颁布后，英国为促进教育机会均等建立的新型学校是（　）", "opts": ["综合中学", "英王学院", "城市学院", "初级学院"], "a": 0, "exp": "此题考查综合中学。A.1944年的《巴特勒教育法》颁布后，到20世纪六七十年代，为促进教育机会均等，英国工党政府将文法中学、技术中学和现代中学合并为一种新型学校，即综合中学。√B.·英王学院是英国国教派于1829年成立的，后来与伦敦大学学院合并为伦敦大学，领导了新大学运动。C.城市学院是在19世纪英国新大学运动中出现的一类学校。D.1892年，美国芝加哥大学校长哈珀提出将四年制大学分为“初级学院”和“高级学院”，兴起了初级学院运动。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 59}},
  {"id": "kc|edu-foreign|wj-06|知识点四|4", "bank": "kc", "subj": "edu-foreign", "ch": "wj-06", "chName": "第六章 英国的近现代教育制度", "sec": "知识点四：20世纪下半叶的英国现代教育制度", "no": 4, "q": "在英国历史上首次以立法的形式规定了学校的基本教学内容的法案是（　）", "opts": ["《巴特勒教育法》．", "《罗宾斯报告》", "《斯宾斯报告》", "《1988年教育改革法》"], "a": 3, "exp": "此题考查《1988年教育改革法》。A.《巴特勒教育法》基本形成了现代英国国民教育制度。B.《罗宾斯报告》探讨了英国高等教育如何为社会服务的问题，提出了“罗宾斯原则”。C.《斯宾斯报告》在《哈多报告》基础上，强调中等教育的多样化，提出设立多科性学校。D.《1988年教育改革法》是继《1944年教育法》之后英国又一个重要的教育法案，在英国历史上首次以立法的形式规定了学校的基本教学内容。√", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 59}},
  {"id": "kc|edu-foreign|wj-06|知识点四|5", "bank": "kc", "subj": "edu-foreign", "ch": "wj-06", "chName": "第六章 英国的近现代教育制度", "sec": "知识点四：20世纪下半叶的英国现代教育制度", "no": 5, "q": "《1988年教育改革法》是英国自第二次世界大战结束以来规模最大的一次教育改革，该法案强调实施全国统一课程，并规定在义务教育阶段开设的三类课程是（　）", "opts": ["核心课程、基础课程、附加课程", "核心课程、专业课程、拓展课程", "基础课程、专业课程、拓展课程", "专业课程、研究课程、附加课程"], "a": 0, "exp": "此题考查《1988年教育改革法》。《1988年教育改革法》对英国教育体制进行全面改革，该法案规定实施全国统一课程，确定在5～16岁的义务教育阶段开设核心课程、基础课程和附加课程。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 59}},
  {"id": "kc|edu-foreign|wj-06|知识点四|6", "bank": "kc", "subj": "edu-foreign", "ch": "wj-06", "chName": "第六章 英国的近现代教育制度", "sec": "知识点四：20世纪下半叶的英国现代教育制度", "no": 6, "q": "下列关于《1988年教育改革法》的描述，错误的是（　）", "opts": ["在高等教育方面，要求废除“双重制", "义务教育阶段学生必须学习国家统一课程", "改革减轻了师生负担", "部分小学可以直接接受中央教育机构的指导"], "a": 2, "exp": "此题考查《1988年教育改革法》。《1988年教育改革法》存在争议，它统一课程，剥夺教师自主权，压抑学生的创造性，有“一刀切”嫌疑，并没有减轻师生负担。此题为选非题，因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 59}},
  {"id": "kc|edu-foreign|wj-06|知识点四|7", "bank": "kc", "subj": "edu-foreign", "ch": "wj-06", "chName": "第六章 英国的近现代教育制度", "sec": "知识点四：20世纪下半叶的英国现代教育制度", "no": 7, "q": "在“罗宾斯原则”的主导下，英国创办的颇具特色的新型高等教育机构是（　）", "opts": ["伦敦大学学院", "苏格兰大学", "开放大学", "哈勒大学"], "a": 2, "exp": "此题考查“罗宾斯原则”。A.20世纪80年代的《雷弗休姆报告》提出要加强和改进高等教育管理，特别是要加强高校内部专业化的管理，从而提高教学和科研水平，承担更多的社会和经济课题。B.《1988年教育改革法》要求废除“双重制”，包括多科技术学院和其他学院在内的高等院校将脱离地方教育当局的管辖而成为“独立”机构。C.是“罗宾斯原则”的含义。√D.《1992年继续教育和高等教育法》建立了新的高等教育质量保证体系，主要包括质量控制、质量审查和质量评估。，【】A.伦敦大学学院：它的成立标志着英国新大学运动的开始。B.苏格兰大学：15一16世纪，苏格兰先后创办的5所大学的总称。苏格兰大学比较注重自然科学和现代外语等实用课程的开设，招收中小资产阶级的子弟人学，收费低廉。C.开放大学：“罗宾斯原则”是20世纪60年代英国高等教育大发展的政策依据，促使接受高等教育的人数快速增长，强调高等教育要适应现代科学进步和社会生产发展对人才的新要求。在这一原则的主导下，英国创办了颇具特色的新型高等教育机构一开放大学。√D.哈勒大学：17一18世纪德国新大学运动的代表学校之一。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 59}},
  {"id": "kc|edu-foreign|wj-06|知识点四|8", "bank": "kc", "subj": "edu-foreign", "ch": "wj-06", "chName": "第六章 英国的近现代教育制度", "sec": "知识点四：20世纪下半叶的英国现代教育制度", "no": 8, "q": "（　）提出了一项全新的教师职前教育和在职培训计划，即著名的“师资培训三段法”，把师资培训分成由个人高等教育、职前教育专业训练和在职进修三个阶段构成的统一体。（　）", "opts": ["《詹姆斯报告》", "《罗宾斯报告》", "《哈多报告》", "《雷弗休姆报告》"], "a": 0, "exp": "此题考查《詹姆斯报告》。A.《詹姆斯报告》提出了著名的“师资培训三段法”，把师资培训分成由个人高等教育、职前教育专业训练和在职进修三个阶段构成的统一体。√B.《罗宾斯报告》探讨了英国高等教育如何为社会服务的问题，提出了“罗宾斯原则”。C.《哈多报告》第一次从国家的角度阐明了初等教育和中等教育衔接，中等教育面向全体儿童的思想。D.《雷弗休姆报告》与加强高等教育质量有关，它的很多建议被后来的政府报告或立法采纳。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 60}},
  {"id": "kc|edu-foreign|wj-06|知识点四|9", "bank": "kc", "subj": "edu-foreign", "ch": "wj-06", "chName": "第六章 英国的近现代教育制度", "sec": "知识点四：20世纪下半叶的英国现代教育制度", "no": 9, "q": "《雷弗休姆报告》主要针对以下哪个教育阶段？（　）", "opts": ["初等教育", "中等教育", "高等教育", "继续教育"], "a": 2, "exp": "此题考查《雷弗休姆报告》。1981一1983.年，英国高等教育研究会连续发表了十多份关于高等教育的调查报告，它们被合称为《雷弗休姆报告》。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 60}},
  {"id": "kc|edu-foreign|wj-06|知识点四|10", "bank": "kc", "subj": "edu-foreign", "ch": "wj-06", "chName": "第六章 英国的近现代教育制度", "sec": "知识点四：20世纪下半叶的英国现代教育制度", "no": 10, "q": "沿着《1988年教育改革法》在高等教育方面继续跟进的法案是（　）", "opts": ["《1992年继续教育和高等教育法》", "《学习社会中的高等教育》", "《詹姆斯报告》", "《雷弗休姆报告》"], "a": 0, "exp": "此题考查英国20世纪下半叶的高等教育。A.《1992年继续教育和高等教育法》是沿着《1988年教育改革法》在高等教育方面继续跟进的法案。√B.《学习社会中的高等教育》是1997年颁布的法案，并没有直接跟进。C.《詹姆斯报告》于1972年颁布。D.《雷弗休姆报告》在1981—1983年间颁布。英国高等教育的“双重制”指的是各类院校由地方管理、大学由中央管理的体制。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 60}},
  {"id": "kc|edu-foreign|wj-06|知识点四|11", "bank": "kc", "subj": "edu-foreign", "ch": "wj-06", "chName": "第六章 英国的近现代教育制度", "sec": "知识点四：20世纪下半叶的英国现代教育制度", "no": 11, "q": "标志着英国高等教育“双重制”的彻底终结的是（　）", "opts": ["罗宾斯原则", "《詹姆斯报告》", "《1988年教育改革法》", "《1992年继续教育和高等教育法》"], "a": 3, "exp": "此题考查《1992年继续教育和高等教育法》。A.“罗宾斯原则”是指应为所有在能力和成绩方面合格的，并愿意接受高等教育的人提供高等教育课程。B.《詹姆斯报告》聚焦师范教育改革，提出“师资培训三段法”。C.《1988年教育改革法》提出废除“双重制”，但并未彻底废除。D.《1992年继续教育和高等教育法》成为英国高等教育体制结构变革的分水岭，标志着英国高等教育“双重制”的彻底终结与新型英国高等教育大众化框架的形成。√", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 60}},
  {"id": "kc|edu-foreign|wj-06|知识点四|12", "bank": "kc", "subj": "edu-foreign", "ch": "wj-06", "chName": "第六章 英国的近现代教育制度", "sec": "知识点四：20世纪下半叶的英国现代教育制度", "no": 12, "q": "英国为了迎接新千年的高等教育的发展而制定的高等教育发展战略是（　）", "opts": ["《1992年继续教育和高等教育法》", "《詹姆斯报告》", "《学习社会中的高等教育》", "《雷弗休姆报告》"], "a": 2, "exp": "此题考查《学习社会中的高等教育》。A.《1992年继续教育和高等教育法》的核心作用是终结高等教育“双重制”。B.《詹姆斯报告》聚焦师范教育改革，提出：“师资培训三段法”。C.为了检讨和评估《罗宾斯报告》以来英国高等教育政策和发展状况，制定面向21世纪的高等教育改革框架与发展战略，英国政府于1997年发表了《学习社会中的高等教育》。√D.《雷弗休姆报告》主要针对高等教育的效率、经费、课程等问题提出建议。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 60}},
  {"id": "kc|edu-foreign|wj-07|知识点一|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-07", "chName": "第七章 法国的近现代教育制度", "sec": "知识点一：17一18世纪的法国近代教育概况", "no": 1, "q": "法国大革命期间，资产阶级提出了很多教育改革的基本主张。以下不属于这一内容的是（　）", "opts": ["主张大力发展职业教育", "主张建立国家教育制度", "主张实行普及义务教育", "提倡教育内容的世俗化、科学化"], "a": 0, "exp": "此题考查法国大革命时期的教育。法国大革命时期，资产阶级主张建立国家教育制度；主张人人享有接受教育的机会和权利，国家应当给予保护并实行普及教育；在教育内容和教师问题上，主张实现世俗化和科学化；教育改革方案还在男女平等教育、成人教育等方面提出了要求。没有涉及职业教育。此题为选非题，因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 60}},
  {"id": "kc|edu-foreign|wj-07|知识点一|2", "bank": "kc", "subj": "edu-foreign", "ch": "wj-07", "chName": "第七章 法国的近现代教育制度", "sec": "知识点一：17一18世纪的法国近代教育概况", "no": 2, "q": "17一18世纪，法国颁布了一系列法案，虽然都没有得到有效实施，但在客观上为法国从封建等级教育制度向近代教育制度的转变铺平了道路，其中不包括（　）", "opts": ["《塔列兰教育法案》", "《康多塞方案》", "《雷佩尔提教育方案》", "《基佐法案》"], "a": 3, "exp": "此题考查法国大革命时期的主要教育改革方案。法国在大革命时期的教育改革中，先后制定了三部具有代表性的教育改革方案，即《塔列兰教育法案》《康多塞方案》《雷佩尔提教育方案》。这些方案内容各异，但都反映了法国资产阶级对教育改革的共同主张，可惜均未付诸实施。《基佐法案》是法国于1833年颁布的与初等教育相关的法案。此题为选非题，因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 61}},
  {"id": "kc|edu-foreign|wj-07|知识点一|3", "bank": "kc", "subj": "edu-foreign", "ch": "wj-07", "chName": "第七章 法国的近现代教育制度", "sec": "知识点一：17一18世纪的法国近代教育概况", "no": 3, "q": "17—18世纪，英法教育的共同点不包括（　）", "opts": ["教育体现双轨制", "教会掌握教育权", "提出义务教育法案", "大学突出古典性"], "a": 2, "exp": "此题考查17一18世纪英国和法国的教育改革。A.17一18世纪英法两国教育体系都呈现双轨制，一轨为贵族和资产阶级子弟设立，另一轨为平民子弟设立。B.17一18世纪英法两国的教会均牢牢掌握教育主导权。C.说法错误，英国和法国于19世纪提出义务教育法案。此题为选非题。√D.17一18世纪英法两国的大学教育都以古典性为核心，课程以古典文学、神学、拉丁语等传统内容为主。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 61}},
  {"id": "kc|edu-foreign|wj-07|知识点二|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-07", "chName": "第七章 法国的近现代教育制度", "sec": "知识点二：19世纪的法国近代教育概况", "no": 1, "q": "法国在19世纪建立了中央集权制，其最高教育管理机构是（　）", "opts": ["国家教育委员会", "教育署", "教育局", "帝国大学"], "a": 3, "exp": "此题考查帝国大学。A.苏联、英国的最高教育管理机构采用该名称。B.美国的联邦教育管理机构采用该名称。C.该名称使用广泛，许多国家都有使用。D.拿破仑建立了法兰西第一帝国，为牢固掌握教育管理权，他建立了以帝国大学为核心的中央集权式的教育管理体制。帝国大学是全国最高教育行政管理机构，专门负责整个帝国的所有公共教育事务。√", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 61}},
  {"id": "kc|edu-foreign|wj-07|知识点二|2", "bank": "kc", "subj": "edu-foreign", "ch": "wj-07", "chName": "第七章 法国的近现代教育制度", "sec": "知识点二：19世纪的法国近代教育概况", "no": 2, "q": "拿破仑建立了法兰西第一帝国，下列关于这一时期的教育说法不正确的是（　）", "opts": ["帝国大学是全国最高教育行政管理机构", "帝国大学的总监由皇帝亲自任命", "帝国大学管理公立学校的教师，薪酬由地方负责", "帝国大学体现了中央集权式的教育管理体制"], "a": 2, "exp": "此题考查法兰西第一帝国时期的教育。这一时期，开办任何学校教育机构都必须得到国家的批准，一切公立学校的教师都由帝国大学管理，薪酬由国家支付。此题为选非题，因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 61}},
  {"id": "kc|edu-foreign|wj-07|知识点二|3", "bank": "kc", "subj": "edu-foreign", "ch": "wj-07", "chName": "第七章 法国的近现代教育制度", "sec": "知识点二：19世纪的法国近代教育概况", "no": 3, "q": "促进了法国19世纪的义务教育发展的法案是（　）", "opts": ["《费里法案》", "《哈比法》", "《基佐法案》", "《富尔法》"], "a": 0, "exp": "此题考查《费里法案》。A.法国19世纪80年代颁布的《费里法案》确立了国民教育义务、免费、世俗化三大原则。√B.《哈比法》是法国20世纪70年代颁布的有关中小学改革措施的法案，难以在实践中完全实施。C.1833年颁布的《基佐法案》大力发展初等教育和师范教育，规定每乡区设立一所小学，教师任教需有资格证书。D.1968年颁布的《富尔法》确立了法国高等教育“自主自治、民主参与、多科性结构”的办学原则。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 61}},
  {"id": "kc|edu-foreign|wj-07|知识点二|4", "bank": "kc", "subj": "edu-foreign", "ch": "wj-07", "chName": "第七章 法国的近现代教育制度", "sec": "知识点二：19世纪的法国近代教育概况", "no": 4, "q": "《费里法案》为法国国民教育的发展奠定了基础，以下不属于《费里法案》三原则的是（　）", "opts": ["义务", "基础", "免费", "世俗化"], "a": 1, "exp": "此题考查《费里法案》。1881年和1882年，法国两次颁布有关义务教育的法令，合称《费里法案》。该法案确立了国民教育义务、免费、世俗化三大原则，而且把这些原则的贯彻实施予以具体化。此题为选非题，因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 61}},
  {"id": "kc|edu-foreign|wj-07|知识点二|5", "bank": "kc", "subj": "edu-foreign", "ch": "wj-07", "chName": "第七章 法国的近现代教育制度", "sec": "知识点二：19世纪的法国近代教育概况", "no": 5, "q": "《费里法案》确立了法国国民教育义务、免费、世俗化的三大原则，而且把这些原则的贯彻实施予以具体化。下列关于义务原则的说法，不正确的是（　）", "opts": ["规定6～13岁为法定义务教育阶段", "接受家庭教育的儿童须自第三年起每年到学校接受一次考试检查", "对不送适龄儿童人校学习的家长予以罚款", "免除公立幼儿园及初等学校的学杂费"], "a": 3, "exp": "此题考查《费里法案》。《费里法案》的免费原则是免除公立幼儿园及初等学校的学杂费，免除师范学校的学费、膳食费与住宿费。A、B、C选项均为义务原则的体现。此题为选非题，因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 61}},
  {"id": "kc|edu-foreign|wj-07|知识点二|6", "bank": "kc", "subj": "edu-foreign", "ch": "wj-07", "chName": "第七章 法国的近现代教育制度", "sec": "知识点二：19世纪的法国近代教育概况", "no": 6, "q": "19世纪，法国的中等教育机构中属于实科性质的学校是（　）", "opts": ["国立中学", "市立中学", "现代中学", "专门学校"], "a": 2, "exp": "此题考查19世纪法国中等教育机构。A、B选项均属于法国19世纪古典性质的中等教育机构，D选项属于法国17一18世纪的高等教育机构，只有C选项属于19世纪法国中等教育机构中具有实科性质的学校。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 61}},
  {"id": "kc|edu-foreign|wj-07|知识点二|7", "bank": "kc", "subj": "edu-foreign", "ch": "wj-07", "chName": "第七章 法国的近现代教育制度", "sec": "知识点二：19世纪的法国近代教育概况", "no": 7, "q": "19世纪，确定每个大学区设一所大学，使得法国传统意义上的“大学”在停办一个世纪之后，重新出现于法国社会的法案是（　）", "opts": ["《国立大学组织法》", "《帝国大学令》", "《费里法案》", "《高等教育指导法》"], "a": 0, "exp": "此题考查《国立大学组织法》。A.《国立大学组织法》确定在原来分散设立学院的基础上组建大学，每个大学区设一所大学。如此，传统意义上的“大学”自1793年被废止后重新现身于法国社会。√B.《帝国大学令》是日本明治维新时期颁布的法令。C.《费里法案》确定了义务、免费、世俗化三原则。D.《高等教育指导法》为干扰选项。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 61}},
  {"id": "kc|edu-foreign|wj-07|知识点二|8", "bank": "kc", "subj": "edu-foreign", "ch": "wj-07", "chName": "第七章 法国的近现代教育制度", "sec": "知识点二：19世纪的法国近代教育概况", "no": 8, "q": "在19世纪为法国教育平等做出突出贡献的是（　）", "opts": ["帝国大学的设立", "《费里法案》的实施", "国立中学与市立中学并行发展", "专科、军事及师范学校的产生"], "a": 1, "exp": "此题考查19世纪法国的教育。A.是为教育管理做出的贡献。B.《费里法案》明确规定所有适龄儿童无论出身、贫富都必须接受初等教育，这一法案直接推动了法国基础教育的普及，极大地促进了教育平等。√C.国立中学与市立中学属于古典文科中学，针对贵族招生，没有体现教育平等。D.体现的是高等教育的发展，不是教育平等。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 61}},
  {"id": "kc|edu-foreign|wj-07|知识点三|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-07", "chName": "第七章 法国的近现代教育制度", "sec": "知识点三：20世纪上半叶的法国现代教育制度", "no": 1, "q": "1919年，法国“统一学校运动”提出的主要主张是（　）", "opts": ["取消教会管理学校的权利", "实施6～18岁的免费义务教育", "打击双轨制", "大力发展职业教育"], "a": 2, "exp": "此题考查“统一学校运动”。“统一学校运动”提出民主教育、择优录取，试图衔接初等和中等教育，其实质就是冲击双轨制，实现单轨教育。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 62}},
  {"id": "kc|edu-foreign|wj-07|知识点三|2", "bank": "kc", "subj": "edu-foreign", "ch": "wj-07", "chName": "第七章 法国的近现代教育制度", "sec": "知识点三：20世纪上半叶的法国现代教育制度", "no": 2, "q": "20世纪初，（）被称为法国“技术教育宪章”，建构了法国职业技术教育的基本框架。（　）", "opts": ["《斯宾斯报告》", "《巴尔福教育法》", "《费里法案》", "《阿斯蒂埃法》"], "a": 3, "exp": "此题考查《阿斯蒂埃法》。A.《斯宾斯报告》是英国1938年颁布的法案，讨论中等教育问题。B.《巴尔福教育法》是英国1902年颁布的法案，调整了英国的教育行政管理体制。C.《费里法案》确立了法国国民教育义务、免费、世俗化三原则。D.1919年颁布的《阿斯蒂埃法》被称为法国“技术教育宪章”，它建构了法国职业技术教育的基本框架。V", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 62}},
  {"id": "kc|edu-foreign|wj-07|知识点三|3", "bank": "kc", "subj": "edu-foreign", "ch": "wj-07", "chName": "第七章 法国的近现代教育制度", "sec": "知识点三：20世纪上半叶的法国现代教育制度", "no": 3, "q": "被誉为法国“技术教育宪章”的法案，其主张不包括（　）", "opts": ["18岁以下的青年接受免费职业教育", "全国每一市镇设立一所职业学校", "国家设立相关部门管理职业教育", "建立全国统一职业教育课程标准"], "a": 3, "exp": "此题考查《阿斯蒂埃法》。《阿斯蒂埃法》被誉为法国“技术教育宪章”，A、B、C选项均为《阿斯蒂埃法》的规定。该法案未提及要建立全国统一职业教育课程标准，只是规定了职业教育内容的大致框架。此题为选非题，因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 62}},
  {"id": "kc|edu-foreign|wj-07|知识点三|4", "bank": "kc", "subj": "edu-foreign", "ch": "wj-07", "chName": "第七章 法国的近现代教育制度", "sec": "知识点三：20世纪上半叶的法国现代教育制度", "no": 4, "q": "（\"）不属于20世纪前期英、法两国在教育改革中主要解决的问题。（　）", "opts": ["学制改革", "加强国家对教育的控制", "普及初等义务教育", "教育民族主义和政治化"], "a": 3, "exp": "此题考查20世纪前期英国和法国的教育改革。A.英国通过一系列法案，推进学制衔接与体系完善；法国开展统一学校运动，主张建立统一的基础教育体系。B.英国通过《巴尔福教育法》确立的地方教育当局体系，进一步细化中央与地方的教育管理权责；法国则巩固中央集权的教育管理模式，统一课程标准和师资培养要求，削弱教会对教育的影响。C.英国完善义务教育的年限与保障机制，推动初等教育的标准化发展；法国则在《费里法案》的基础上，进一步落实义务教育的执行力度，保障适龄儿童的受教育权利。D.两国改革的重点是解决教育公平、学制衔接、国家管控等内部教育发展问题，而非通过教育强化民族主义宣传或政治意识形态灌输。此题为选非题。√", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 62}},
  {"id": "kc|edu-foreign|wj-07|知识点四|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-07", "chName": "第七章 法国的近现代教育制度", "sec": "知识点四：20世纪下半叶的法国现代教育制度", "no": 1, "q": "（　）虽未实施，却指引了法国民主化和现代化发展的方向，被誉为法国教育史的“第二次革命”。（　）", "opts": ["《费里法案》", "《关于统一学校教育事业的修正协定》", "《郎之万一瓦隆教育改革方案》", "《法国学校体制现代化建议》"], "a": 2, "exp": "此题考查《郎之万一瓦隆教育改革方案》。A.《费里法案》：法国19世纪80年代的法案，确立了国民教育义务、免费、世俗化三原则。B.《关于统一学校教育事业的修正协定》：德国20世纪60年代的法案，也称《汉堡协定》。C.《郎之万一瓦隆教育改革方案》：因历史因素未实施，但为战后法国的教育指明了方向，被誉为法国教育史的“第二次革命”。√D.《法国学校体制现代化建议》：也称《哈比法》，因要求较高，改革步子过大，难以在实践中完全实施。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 62}},
  {"id": "kc|edu-foreign|wj-07|知识点四|2", "bank": "kc", "subj": "edu-foreign", "ch": "wj-07", "chName": "第七章 法国的近现代教育制度", "sec": "知识点四：20世纪下半叶的法国现代教育制度", "no": 2, "q": "《郎之万一瓦隆教育改革方案》虽未实施，但却被看作“二战”后法国最杰出的法案，其主要原因是（　）", "opts": ["后来的法案都是沿着这一法案实施成功的", "其突出了教育现代化和教育民主化的趋势和方向", "其设想是符合国情的", "未实施是由法国的客观情况造成的，法案本身的设置没有问题"], "a": 1, "exp": "此题考查《郎之万一瓦隆教育改革方案》。A.后来的法案并不都是沿着这一法案实施成功的。B.《郎之万一瓦隆教育改革方案》虽未实施，但突出了教育现代化和教育民主化的趋势和方向。√C.《郎之万一瓦隆教育改革方案》是不符合国情的，所以没能实施。D.法案本身并不是完美无缺的。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 62}},
  {"id": "kc|edu-foreign|wj-07|知识点四|3", "bank": "kc", "subj": "edu-foreign", "ch": "wj-07", "chName": "第七章 法国的近现代教育制度", "sec": "知识点四：20世纪下半叶的法国现代教育制度", "no": 3, "q": "由于《郎之万一瓦隆教育改革方案》未实施，法国为了实现教育强国梦又颁布了新的法案，要求中等教育第二阶段实行短期职业型、长期职业型、短期普通型、长期普通型的新学制体系。该法案是（　）", "opts": ["《国家与私立学校关系法》", "《教育改革法》", "《法国学校体制现代化建议》", "《富尔法》"], "a": 1, "exp": "此题考查《教育改革法》。A.《国家与私立学校关系法》：法国于1959年颁布，规定国家给予私立学校财政资助，私立学校采用公立学校的生活规则和教学大纲，接受国家监督。B.《教育改革法》：法国于1959年颁布，规定中等教育分为两个阶段，第一阶段为两年观察期，第二阶段分为四种类型，即短期职业型、长期职业型、短期普通型、长期普通型。√C.《法国学校体制现代化建议》：也称《哈比法》，因要求较高，改革步子过大，难以在实践中完全实施。D.《富尔法》：1968年颁布，确立了法国高等教育“自主自治、民主参与、多科性结构”的办学原则。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 62}},
  {"id": "kc|edu-foreign|wj-07|知识点四|4", "bank": "kc", "subj": "edu-foreign", "ch": "wj-07", "chName": "第七章 法国的近现代教育制度", "sec": "知识点四：20世纪下半叶的法国现代教育制度", "no": 4, "q": "“二战”后，提出国家与私立学校建立契约，国家给予私立学校补助金，要求私立学校以公立学校制度办学，并接受国家监督的法案是（　）", "opts": ["《国家与私立学校关系法》", "《高等教育方向指导法》", "《郎之万一瓦隆教育改革方案》", "《教育改革法》"], "a": 0, "exp": "此题考查《国家与私立学校关系法》。A.《国家与私立学校关系法》于1959年颁布，规定国家给予私立学校财政资助，私立学校采用公立学校的生活规则和教学大纲，接受国家监督。√B.《高等教育方向指导法》确立了法国高等教育“自主自治、民主参与、多科性结构”的办学原则。C.《郎之万一瓦隆教育改革方案》因历史因素未实施，但为战后法国的教育指明了方向，并被称为法国教育史的“第二次革命”。D.《教育改革法》于1959年颁布，规定法国中等教育分为两个阶段，第一阶段为两年观察期，第二阶段分为四种类型，即短期职业型、长期职业型、短期普通型、长期普通型。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 62}},
  {"id": "kc|edu-foreign|wj-07|知识点四|5", "bank": "kc", "subj": "edu-foreign", "ch": "wj-07", "chName": "第七章 法国的近现代教育制度", "sec": "知识点四：20世纪下半叶的法国现代教育制度", "no": 5, "q": "20世纪60年代，旨在改进政府对大学的控制，使高等教育的专业设置更符合经济和科技发展及国际竞2争需要，确立法国高等教育发展的“民主”“自治”“多学科”原则的教育法案是（　）", "opts": ["《郎之万一瓦隆教育改革方案》", "《法国学校体制现代化建议》", "《大学令》", "《高等教育方向指导法》"], "a": 3, "exp": "此题考查《高等教育方向指导法》（《富尔法》）。A.《郎之万一瓦隆教育改革方案》因历史因素未实施，但为战后法国的教育指明了方向，被誉为法国教育史的“第二次革命”。B.《法国学校体制现代化建议》即《哈比法》，重点是改革中小学教育，但因要求较高，改革步子过大，难以在实践中完全实施。C.《大学令》是日本1918年颁布的法案，使日本出现并发展了多类大学，培养了大批学术人才与技术人才。要求按照新的原则调整和改组法国的大学。按照这三项原则，大学是享有教学、行政和财政自主权的国家机构。√", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 62}},
  {"id": "kc|edu-foreign|wj-07|知识点四|6", "bank": "kc", "subj": "edu-foreign", "ch": "wj-07", "chName": "第七章 法国的近现代教育制度", "sec": "知识点四：20世纪下半叶的法国现代教育制度", "no": 6, "q": "现代法国的教育改革中，在普通学校中以加强职业教育为目的的是（　）", "opts": ["《哈比法》", "《郎之万一瓦隆教育改革方案》", "《教育改革法》", "《高等教育方向指导法》"], "a": 0, "exp": "此题考查《法国学校体制现代化建议》（《哈比法》）。A.1975年，法国议会通过了《法国学校体制现代化建议》（《哈比法》），重点是加强法国的职业教育。VB.《郎之万一瓦隆教育改革方案》因历史因素未实施，但为战后法国的教育指明了方向，被誉为法国教育史的“第二次革命”。C.《教育改革法》于1959年颁布，规定法国中等教育分为两个阶段，第一阶段为两年观察期，第二阶段分为四种类型，即短期职业型、长期职业型、短期普通型、长期普通型。D.《高等教育方向指导法》确立了法国高等教育“自主自治、民主参与、多科性结构”的办学原则。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 62}},
  {"id": "kc|edu-foreign|wj-07|知识点四|7", "bank": "kc", "subj": "edu-foreign", "ch": "wj-07", "chName": "第七章 法国的近现代教育制度", "sec": "知识点四：20世纪下半叶的法国现代教育制度", "no": 7, "q": "进人20世纪70年代后，为进一步改进普通学校教育体制，法国议会通过了《法国学校体制现代化建议》，实行“三分制教学法”。下列属于“三分制教学法”的课程组合形式的是（　）", "opts": ["体育课程、工具课程、劳动课程", "工具课程、启蒙性课程、艺术课程", "工具课程、启蒙性课程、体育课程", "劳动课程、启蒙性课程、体育课程"], "a": 2, "exp": "此题考查《法国学校体制现代化建议》（《哈比法》）。《法国学校体制现代化建议》即《哈比法》，其中的“三分制教学法”把教学内容分为工具课程（数学与法语）、启蒙性课程（历史、地理、公民道德、人文科学、自然科学、艺术等）和体育课程三个部分。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 63}},
  {"id": "kc|edu-foreign|wj-07|知识点四|8", "bank": "kc", "subj": "edu-foreign", "ch": "wj-07", "chName": "第七章 法国的近现代教育制度", "sec": "知识点四：20世纪下半叶的法国现代教育制度", "no": 8, "q": "）规定法国建立一种完全统一的，向所有学生开放的综合性教育机构一—综合中学。这是法国继(统一小学以后，在教育民主化进程中又迈出的重要一步。（　）", "opts": ["《哈比法》", "《费里法案》", "《郎之万一瓦隆教育改革方案》", "《富尔法》"], "a": 0, "exp": "此题考查《法国学校体制现代化建议》（《哈比法》）。A.《哈比法》于1975年由法国教育部长哈比提出，核心是推动中等教育民主化，建立统一的综合中学，取消传统的双轨制（认为学术轨与职业轨分流过早），强调为所有学生提供共同的基础教育阶段。√B.《费里法案》确立了法国国民教育的三大原则——义务、免费、世俗化，奠定了现代小学教育基础，但未涉及中学改革。C.《郎之万一瓦隆教育改革方案》主张建立方向指导原则和统一学校体系，但因政局变动未被实施，且未明确提出综合中学的概念。D.《富尔法》提出了“自主自治、民主参与、多科性结构”原则，要求重塑大学管理体制，与中等教育的综合中学无关。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 63}},
  {"id": "kc|edu-foreign|wj-07|知识点四|9", "bank": "kc", "subj": "edu-foreign", "ch": "wj-07", "chName": "第七章 法国的近现代教育制度", "sec": "知识点四：20世纪下半叶的法国现代教育制度", "no": 9, "q": "法国在“二战”之后非常注重对基础教育课程的改革，其中，主张既要做好从小学到高中课程融为一体的纵向改革，又要做好各科知识融会贯通的横向改革的法案是（>（　）", "opts": ["《哈比法》", "《课程宪章》", "《教育改革法》", "《富尔法》"], "a": 1, "exp": "此题考查《课程宪章》。A.1975年，法国议会通过了《法国学校体制现代化建议》（《哈比法》），重点是改革中小学教育。B.1992年，法国颁布了《课程宪章》。该法案对学科体系进行综合改革，既有从小学到高中课程融为一体的纵向综合改革，也有各科知识融会贯通的横向综合改革等。√C.《教育改革法》于1959年颁布，规定法国中等教育分为两个阶段，第一阶段为两年观察期，第二阶段分为四种类型，即短期职业型、长期职业型、短期普通型、长期普通型。D.《富尔法》于1968年颁布，确立了法国高等教育“自主自治、民主参与、多科性结构”的办学原则。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 63}},
  {"id": "kc|edu-foreign|wj-07|知识点四|10", "bank": "kc", "subj": "edu-foreign", "ch": "wj-07", "chName": "第七章 法国的近现代教育制度", "sec": "知识点四：20世纪下半叶的法国现代教育制度", "no": 10, "q": "下列关于法国的教育特色“方向指导”的说法，不正确的是（　）", "opts": ["在“统一劳动学校”中设置“方向指导班”作为学制改革的开始", "在《郎之万一瓦隆教育改革方案》中设置方向指导班", "《教育改革法》颁布后，“市立初级中学”问世，它是具有方向指导性质的普通初级中学", "《哈比法》中的方向指导期为两年，是为了让学生增加与社会的联系"], "a": 0, "exp": "此题考查法国的教育特色“方向指导”。B、C、D选项均正确，均为法国关于“方向指导”的教育特点。A选项为苏联的教育改革，并且苏联没有“方向指导班”。此题为选非题，因此，答案选A。深联系微信1931637日日日", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 63}},
  {"id": "kc|edu-foreign|wj-08|知识点一|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-08", "chName": "第八章 德国的近现代教育制度", "sec": "知识点一：17一18世纪的德国近代教育概况", "no": 1, "q": "巴西多为泛爱学校编写了（　），被誉为18世纪的《世界图解》，是教育史上第二本有插图的教科书。（　）", "opts": ["《母育学校》", "《人的教育》", "《童年的秘密》", "《初级读本》"], "a": 3, "exp": "此题考查巴西多的教育著作。A.《母育学校》是夸美纽斯的著作，是西方教育史上第一本学前教育学著作。B.《人的教育》是福禄培尔的著作。C.《童年的秘密》是蒙台梭利的著作。D.巴西多的《初级读本》附有100幅插图，被誉为18世纪的《世界图解》，是教育史上第二本有插图的教科书。√", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 63}},
  {"id": "kc|edu-foreign|wj-08|知识点一|2", "bank": "kc", "subj": "edu-foreign", "ch": "wj-08", "chName": "第八章 德国的近现代教育制度", "sec": "知识点一：17一18世纪的德国近代教育概况", "no": 2, "q": "18世纪后期的德国，受卢梭和夸美纽斯教育思想影响出现的重视教授实用知识，关注儿童兴趣，寓教学于游戏之中的新式学校是（　）", "opts": ["文科学校", "实科学校", "泛爱学校", "劳作学校"], "a": 2, "exp": "此题考查泛爱学校。A.文科学校具有强烈的古典主义倾向。B.实科学校主要学习实科知识，其出现与工商业的发展和城市生活的丰富有关。C.泛爱学校以泛爱主义为宗旨，提倡实物教学和儿童主动学习，重视知识的实用性和儿童的兴趣，寓教学于游戏之中。√伦理化”为任务。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 63}},
  {"id": "kc|edu-foreign|wj-08|知识点一|3", "bank": "kc", "subj": "edu-foreign", "ch": "wj-08", "chName": "第八章 德国的近现代教育制度", "sec": "知识点一：17一18世纪的德国近代教育概况", "no": 3, "q": "泛爱学校是自然主义教育思想在德国的实践。下列不属于它的作用与影响的是（　）", "opts": ["反对封建主义", "反对经院哲学", "反对古典主义", "反对实用主义"], "a": 3, "exp": "此题考查泛爱学校。自然主义思想反对封建主义、古典主义、传统的经院哲学，但不反对实用主义，且实用主义是在自然主义之后出现的。此题为选非题，因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 63}},
  {"id": "kc|edu-foreign|wj-08|知识点一|4", "bank": "kc", "subj": "edu-foreign", "ch": "wj-08", "chName": "第八章 德国的近现代教育制度", "sec": "知识点一：17一18世纪的德国近代教育概况", "no": 4, "q": "现套课程公众号【研大】关于18世纪后期德国的泛爱学校，以下说法错误的是（　）", "opts": ["受到卢梭和夸美纽斯的影响", "与赫尔巴特的儿童管理相对立", "重视德语，也开设外国语", "教师可以适当进行体罚"], "a": 3, "exp": "此题考查泛爱学校。德国的泛爱学校受到卢梭和夸美纽斯自然主义思想的影响；因过于注重儿童的自由而受到了赫尔巴特等人的批评；重视本民族语言，也开设外国语；严禁体罚。此题为选非题，因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 63}},
  {"id": "kc|edu-foreign|wj-08|知识点一|5", "bank": "kc", "subj": "edu-foreign", "ch": "wj-08", "chName": "第八章 德国的近现代教育制度", "sec": "知识点一：17一18世纪的德国近代教育概况", "no": 5, "q": "18世纪，德国的实科中学是一种新型的学校，既具有（）教育的性）教育的性质，又具有（质，因而获得了快速的发展。（　）", "opts": ["普通；职业", "普通；师范", "师范；职业", "职业；高等"], "a": 0, "exp": "此题考查德国实科中学的性质。实科中学反对学习古典知识，主张学习具有实用性的自然科学知识，用现代语教学，加强了科学与教育的联系。实科中学的学生大多无法升人大学，只能进人职业领域，这种教育实际上开创了职业教育的先河。所以，实科中学既具有普通教育的性质，又具有职业教育的性质。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 64}},
  {"id": "kc|edu-foreign|wj-08|知识点一|6", "bank": "kc", "subj": "edu-foreign", "ch": "wj-08", "chName": "第八章 德国的近现代教育制度", "sec": "知识点一：17一18世纪的德国近代教育概况", "no": 6, "q": "（　）作为欧洲第一所新式大学，是新大学运动的中心。（　）", "opts": ["哥廷根大学", "哈勒大学", "柏林大学", "慕尼黑大学"], "a": 1, "exp": "此题考查哈勒大学。A.哥廷根大学是典型的新式大学，但诞生于哈勒大学之后。B.德国新大学运动中诞生了哈勒大学，它是欧洲第一所新式大学，是新大学运动的中心。√C.柏林大学是德国于1810年建立的，它是世界上第一个建立了现代大学制度的高等学府。D.慕尼黑大学是德国传统大学。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 64}},
  {"id": "kc|edu-foreign|wj-08|知识点二|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-08", "chName": "第八章 德国的近现代教育制度", "sec": "知识点二：19世纪的德国近代教育概况", "no": 1, "q": "世界上第一所幼儿园创办于（　）", "opts": ["德国", "法国", "美国", "英国"], "a": 0, "exp": "此题考查19世纪德国学前教育的概况。19世纪，德国教育家福禄培尔创办了世界上第一所幼儿园，此后德国各地纷纷创办幼儿园，德国的学前教育走在了世界前列。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 64}},
  {"id": "kc|edu-foreign|wj-08|知识点二|2", "bank": "kc", "subj": "edu-foreign", "ch": "wj-08", "chName": "第八章 德国的近现代教育制度", "sec": "知识点二：19世纪的德国近代教育概况", "no": 2, "q": "19世纪初，在民族丧失独立、经济十分困难的情况下，德国创办了一所新式大学，它是世界上第一个建立了现代大学制度的高等学府。这所大学是（　）", "opts": ["慕尼黑大学", "哥廷根大学", "柏林大学", "哈勒大学"], "a": 2, "exp": "此题考查柏林大学。德国于1810年建立了柏林大学，它是在民族丧失独立、经济十分困难的情况下创办的。它是世界上第一个建立了现代大学制度的高等学府，是世界高等教育的典范。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 64}},
  {"id": "kc|edu-foreign|wj-08|知识点二|3", "bank": "kc", "subj": "edu-foreign", "ch": "wj-08", "chName": "第八章 德国的近现代教育制度", "sec": "知识点二：19世纪的德国近代教育概况", "no": 3, "q": "下列哪所大学的建立没有受到柏林大学的影响？（　）", "opts": ["东京大学", "北京大学", "约翰斯·霍普金斯大学", "牛津大学"], "a": 3, "exp": "此题考查柏林大学。A.日本仿照柏林大学建立了东京大学，这是日本现代大学的开端。B.蔡元培将柏林大学的理念运用在北京大学的改革中。C.美国效仿柏林大学创建了约翰斯·霍普金斯大学，该校成为美国高等教育改革的引领者。D.牛津大学是著名的中世纪大学，此时柏林大学还未成立。√", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 64}},
  {"id": "kc|edu-foreign|wj-08|知识点二|4", "bank": "kc", "subj": "edu-foreign", "ch": "wj-08", "chName": "第八章 德国的近现代教育制度", "sec": "知识点二：19世纪的德国近代教育概况", "no": 4, "q": "关于柏林大学，下列说法不正确的是（　）", "opts": ["柏林大学的真正使命在于提高学术研究水平", "柏林大学采用了“习明纳”这一教学组织形式，主张教学与研究相结合", "柏林大学是世界上第一个建立了现代大学制度的高等学府", "按领导体制，柏林大学可分为“学生”大学与“先生”大学"], "a": 3, "exp": "此题考查柏林大学。“学生”大学与“先生”大学是中世纪大学按领导体制进行的划分，与柏林大学无关。柏林大学的教学管理秉承“教自由”“学自由”。此题为选非题，因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 64}},
  {"id": "kc|edu-foreign|wj-08|知识点二|5", "bank": "kc", "subj": "edu-foreign", "ch": "wj-08", "chName": "第八章 德国的近现代教育制度", "sec": "知识点二：19世纪的德国近代教育概况", "no": 5, "q": "德国19世纪的柏林大学与17一18世纪新大学运动中的哈勒大学和哥廷根大学，最根本的不同之处是（　）", "opts": ["倡导自由的办学原则", "采用讨论的教学方法", "倡导学校自治", "把科学研究看作大学发展的最高宗旨"], "a": 3, "exp": "此题考查柏林大学的特点。A、B、C选项是相同点。D选项是不同点，把科学研究看作大学发展的最高宗旨是柏林大学最大的特点。虽然哈勒大学和哥廷根大学也把科学研究看作大学的任务之一，但是并没有把它放在最高宗旨的地位上。因此，答案选D。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 64}},
  {"id": "kc|edu-foreign|wj-08|知识点二|6", "bank": "kc", "subj": "edu-foreign", "ch": "wj-08", "chName": "第八章 德国的近现代教育制度", "sec": "知识点二：19世纪的德国近代教育概况", "no": 6, "q": "下列关于柏林大学与北京大学改革的对比，错误的是（　）", "opts": ["都是民族危亡、国家落后时期的改革", "都注重科研，将哲学视为最高学问而看轻职业性专业", "柏林大学是世界高等教育的典范，北京大学引领中国高等教育的发展方向", "柏林大学侧重“教自由”“学自由”，北京大学侧重“思想自由，兼容并包"], "a": 1, "exp": "此题考查柏林大学与北京大学改革的对比。柏林大学与北京大学改革对比表维度柏林大学北京大学德国在普法战争中丧失大片国土，哈勒大学、哥廷根背景外受列强压迫，内有军阀混战，北大自身腐败混乱大学等知名大学丢失人物洪堡蔡元培宗旨：倡科研，斥职业抱定宗旨，改变校风管理：“教自由”“学自由”“思想自由，兼容并包”措施学生：培育研究型人才；“习明纳”教授治校；民主管理教师：聘请学术型教师学科与教学体制改革对德国：德国科学和艺术的中心；德国经济进步的对北大：“思想自由，兼容并包”是改革成功的金钥匙。象征。影响对高等教育：高等教育近代化发展中的里程碑。对世界：世界上第一个建立了现代大学制度的高等学对其他领域：新文化新思想的传播中心府；世界高等教育的典范B选项中，柏林大学将哲学视为最高学问而看轻职业性专业；北京大学各个专业地位平等，偏重文理，沟通文理，后取消文、理、法三科界限，实行选科制。此题为选非题，因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 64}},
  {"id": "kc|edu-foreign|wj-08|知识点三|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-08", "chName": "第八章 德国的近现代教育制度", "sec": "知识点三：20世纪上半叶的德国现代教育制度", "no": 1, "q": "德国从初等教育着手，开始废除双轨制是在（）时期。（　）", "opts": ["魏玛共和国", "纳粹", "联邦德国", "德意志帝国"], "a": 0, "exp": "此题考查魏玛共和国时期的教育。魏玛共和国时期，德国在初等教育上废除双轨学制，实行四年制的统一初等学校制度，并实施八年义务教育后教育，还为完成义务教育的毕业生提供补习学校，使其接受职业继续教育。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 64}},
  {"id": "kc|edu-foreign|wj-08|知识点四|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-08", "chName": "第八章 德国的近现代教育制度", "sec": "知识点四：20世纪下半叶的德国现代教育制度", "no": 1, "q": "1959年，联邦德国公布《改组和统一公立普通学校教育的总纲计划》，建议设置三种中学以培养不同层次的人才，这三种中学是（　）", "opts": ["主要中学、学术中学、实科学校", "高级中学、技术中学、完全中学", "现代中学、实科学校、文法中学", "主要学校、实科学校、高级中学"], "a": 3, "exp": "此题考查《改组和统一公立普通学校教育的总纲计划》（《总纲计划》）。《改组和统一公立普通学校教育的总纲计划》在中等教育上，建议设置三种中学，即主要学校、实科学校和高级中学，分别培养不同层次的人才。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 65}},
  {"id": "kc|edu-foreign|wj-08|知识点四|2", "bank": "kc", "subj": "edu-foreign", "ch": "wj-08", "chName": "第八章 德国的近现代教育制度", "sec": "知识点四：20世纪下半叶的德国现代教育制度", "no": 2, "q": "《改组和统一公立普通学校教育的总纲计划》建议在中等教育阶段设置三种中学，分别培养不同层次的人才，其中下层子弟可以进入的中学是（（　）", "opts": ["主要学校", "实科学校", "高级中学", "国民学校"], "a": 0, "exp": "此题考查《改组和统一公立普通学校教育的总纲计划》（《总纲计划》）。A.《改组和统一公立普通学校教育的总纲计划》建议设置主要学校、实科学校和高级中学，分别培养不同层次的人才。其中，主要学校是为下层子弟开设的，是层次最低的一种中学。√B.实科学校以科学教育为重点。C.高级中学包括完全中学和学术中学，前者招收完成促进阶段教育的学生，后者吸收基础学校毕业生中有特殊才能的学生。D.国民学校是德意志帝国时期产生的为下层阶级设立的学校。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 65}},
  {"id": "kc|edu-foreign|wj-08|知识点四|3", "bank": "kc", "subj": "edu-foreign", "ch": "wj-08", "chName": "第八章 德国的近现代教育制度", "sec": "知识点四：20世纪下半叶的德国现代教育制度", "no": 3, "q": "受苏联卫星上天的冲击，联邦德国颁布的关于如何改进普通初等教育和中等教育的法案是（　）", "opts": ["《高等学校总纲法》", "《汉堡协定》", "《总纲计划》", "《国防教育法》"], "a": 2, "exp": "此题考查《改组和统一公立普通学校教育的总纲计划》（《总纲计划》）。A.《高等学校总纲法》是联邦德国于1976年颁布的，是关于高等教育方面的改革法案，与题干中普通初等教育和中等教育的内容不符。B.《汉堡协定》是联邦德国在1964年颁布的。该法案虽然涉及教育统一等方面，但并不是因受苏联卫星上天的冲击而颁布的针对普通初等教育和中等教育的法案。C.1959年，受苏联卫星上天的冲击，联邦德国公布实施了《总纲计划》。该法案主要探讨了如何改进普通初等教育和中等教育的问题，提出了一系列教育改革的建议和措施。√D.《国防教育法》是美国于1958年颁布的，旨在应对苏联卫星上天带来的科技竞争压力，与联邦德国无关。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 65}},
  {"id": "kc|edu-foreign|wj-08|知识点四|4", "bank": "kc", "subj": "edu-foreign", "ch": "wj-08", "chName": "第八章 德国的近现代教育制度", "sec": "知识点四：20世纪下半叶的德国现代教育制度", "no": 4, "q": "第二次世界大战后，联邦德国规定联邦各州的所有儿童均应接受九年义务教育的法案是（　）", "opts": ["《总纲计划》", "《汉堡协定》", "《高等学校总纲法》", "《教育基本法》"], "a": 1, "exp": "此题考查《关于统一学校教育事业的修正协定》（《汉堡协定》）。A.《总纲计划》在初等教育方面建议所有儿童均接受四年的基础学校教育，然后再接受两年的促进阶段教育。B.《汉堡协定》规定所有儿童均应接受九年义务教育，义务教育阶段应是全日制学校的教育。√C.《高等学校总纲法》是针对高等教育进行改革的。D.《教育基本法》是日本于1947年颁布的法案，说明了教育发展的宗旨和原则。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 65}},
  {"id": "kc|edu-foreign|wj-08|知识点四|5", "bank": "kc", "subj": "edu-foreign", "ch": "wj-08", "chName": "第八章 德国的近现代教育制度", "sec": "知识点四：20世纪下半叶的德国现代教育制度", "no": 5, "q": "第二次世界大战后，联邦德国第一部有权威的高等教育方面的法案是（　）", "opts": ["《总纲计划》", "《汉堡协定》", "《高等学校总纲法》", "《德国宪法》"], "a": 2, "exp": "此题考查《高等学校总纲法》。A.《总纲计划》在初等教育方面建议所有儿童均接受四年的基础学校教育，然后再接受两年的促进阶段教育。B.《汉堡协定》规定所有儿童均应接受九年义务教育，义务教育阶段应是全日制学校的教育。C.《高等学校总纲法》是“二战”后联邦德国第一部有权威的高等教育方面的法案。其精神实质是既保留传统大学民主自治的特色，又注重发掘大学的潜力，以适应新的国际竞争的需要。√深联系微信1931637日8日D.《德国宪法》只是对教育发展提出宏观原则性要求，而不是专门针对高等教育的法案。·", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 65}}
]);
